# Generated from tools/data/rulebooks/mille_bornes.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class MilleBornes
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:race, GameRoomRules.translate("The race to exactly 1000 miles"),
            GameRoomRules.translate("Travel exactly 1000 miles before your opponents. Distance cards cover 25, 50, 75, 100 or 200 miles. You cannot pass the finish line. Each player or team may play at most two 200-mile cards in a round."),
            GameRoomRules.translate("Everyone starts stopped with six cards. On your turn, draw a card, then play or discard one. You may discard even when a legal play is available. Nobody may take a discarded card. With an empty draw pile, continue with your remaining cards. The round ends immediately when somebody reaches 1000 miles or any player has no cards left.")),
          rule_section(:hazards, GameRoomRules.translate("Hazards and remedies"),
            GameRoomRules.translate("Play a green light to start driving. A red light stops an opponent. Out of gas requires fuel, a flat tire requires a spare tire, and an accident requires repairs. After these three remedies, you also need a green light before driving again."),
            GameRoomRules.translate("A speed limit allows only 25- and 50-mile cards until an end of speed limit is played. A speed limit can also affect a stopped car. Without attack accumulation, you cannot impose another main hazard on an already stopped opponent. You cannot attack your own team.")),
          rule_section(:safeties, GameRoomRules.translate("Permanent protection"),
            GameRoomRules.translate("An extra tank protects against running out of gas, puncture-proof tires protect against flat tires, and the driving ace protects against accidents and counterflow. Right of way protects against red lights and speed limits and removes the need for green lights. A safety removes the corresponding current problem and protects you until the round ends."),
            GameRoomRules.translate("Playing a safety earns 100 points and gives you another turn. Teammates share protection but keep separate hands.")),
          rule_section(:dirty_tricks, GameRoomRules.translate("Dirty tricks"),
            GameRoomRules.translate("Immediately after an attack, play the matching safety from your hand, even outside your normal turn. This opportunity ends when the next player draws or plays. Moving the cursor or opening information does not end it."),
            GameRoomRules.translate("A dirty trick cancels the attack and preserves the previous driving state. It earns 300 bonus points in addition to the safety's 100 points. Draw a replacement card if one is available, then take an extra turn with its normal draw. Play continues with the player after you; intervening players are skipped. A safety played later gives ordinary protection without this bonus."),
            GameRoomRules.translate("With the bot move delay set to 0, the next bot may draw immediately after the attack is presented, before you can react. Set a nonzero bot move delay for more comfortable dirty tricks. No reaction time is guaranteed: the opportunity still ends when the next player draws or plays. The default bot move delay in 1000 miles is 1 second.")),
          rule_section(:scoring, GameRoomRules.translate("Mileage and victory bonuses"),
            GameRoomRules.translate("Your current mileage contributes to your score. Normally, distance cards add miles; under counterflow, they subtract miles without going below zero. Each safety scores 100 points; a dirty trick adds 300. Reaching exactly 1000 miles earns a 300-point victory bonus. Reaching the finish with an empty draw pile adds another 300 points."),
            GameRoomRules.translate("The round winner earns another 500 points if every opponent or opposing team still has zero miles, and another 300 points if the winning side has played all four safeties. No victory bonuses are awarded when a hand becomes empty. Scores carry over between rounds.")),
          rule_section(:teams, GameRoomRules.translate("Individual and team races"),
            GameRoomRules.translate("Teammates share mileage, hazards, protection and points. Each player keeps a separate hand and takes a separate turn. Four players may form two pairs. Six may form two teams of three or three pairs. Eight may form two teams of four or four pairs.")),
          rule_section(:variants, GameRoomRules.translate("Optional rules"),
            GameRoomRules.translate("Attack accumulation allows several different problems at once, including attacks on an already stopped car. A red light is an exception: it can only be played on a moving car, even with attack accumulation enabled. Resolve every blocking problem before driving. An identical active problem cannot be added twice."),
            GameRoomRules.translate("Discard recycling refills an exhausted draw pile by shuffling discarded cards. Cards in hands or already played on the track are not recycled."),
            GameRoomRules.translate("Add safety cards is on by default: the standard deck contains 106 cards, including the four safeties. Turning it off removes those four cards, leaving 102 cards without permanent protection or dirty tricks. Optional counterflow cards are added separately. Existing games without this setting still include safeties."),
            GameRoomRules.translate("Counterflow is optional and off by default. Add counterflow cards normally adds 4 counterflow attacks and 6 end of counterflow cards, matching the standard speed-limit and end-of-speed-limit counts. These are approved local defaults, not verified QuentinC Playroom deck counts. Existing games retain their explicitly saved counts. Custom deck lets you change both counts separately."),
            GameRoomRules.translate("A counterflow attack can affect an opponent even while stopped. It is independent of speed limits and mechanical hazards and does not require attack accumulation. An already active counterflow cannot be added twice. Driving ace prevents this attack, removes an active counterflow and can be played immediately as a dirty trick against it."),
            GameRoomRules.translate("Under counterflow, each otherwise legal 25-, 50-, 75-, 100- or 200-mile card subtracts its distance instead of adding it. Mileage cannot fall below zero: 100 miles minus a 200-mile card becomes 0, and playing a distance card at 0 leaves it at 0. You must still be able to drive: green-light requirements, blocking hazards, speed limits and the maximum of two 200-mile cards per round still apply, including when those cards subtract miles."),
            GameRoomRules.translate("End of counterflow removes only the counterflow effect. It does not remove a speed limit, a red light or a mechanical hazard, and does not itself require an extra green light. Any green light or remedy still required for another reason remains necessary.")),
          rule_section(:instant_repair, GameRoomRules.translate("Instant repair"),
            GameRoomRules.translate("Add instant repair cards is optional and off by default. When enabled, it adds two instant repair cards to the standard deck. Custom deck lets you change their count; the switch still decides whether they are included."),
            GameRoomRules.translate("After drawing on your normal turn, play an instant repair on your own car or team and choose exactly one problem to remove: a red light, no initial green light, out of gas, a flat tire, an accident, a speed limit or counterflow. One card resolves only the selected problem, even when several problems have accumulated."),
            GameRoomRules.translate("Removing a red light or the lack of an initial green light allows driving only if no other problem blocks it. Repairing a fuel, tire or accident problem still requires a green light unless you have Right of way. Other problems remain unchanged. Instant repair is not a safety or an immediate response to an attack: it grants no immunity, extra turn, or 100- or 300-point bonus.")),
          rule_section(:custom_deck, GameRoomRules.translate("Custom deck"),
            GameRoomRules.translate("Custom deck allows a separate count for every card type: all five distances, every remedy and hazard, each safety, counterflow, end of counterflow and instant repair. Choose an integer from 0 to 100 for each type. Add safety cards, Add counterflow cards and Add instant repair cards still control inclusion: a disabled group stays out of the deck even if its saved counts are positive. The limit of two 200-mile cards per player or team per round does not change."),
            GameRoomRules.translate("The included cards must provide at least six cards per player for the initial deal and allow some points to be scored: include a safety, or distance cards together with a green light, Right of way or instant repair. This does not guarantee that 1000 miles can be reached. Invalid custom decks cannot start. Changing table settings does not rewrite an existing game's deck or replay. Custom deck is off by default; turning it off restores standard counts for new games.")),
          rule_section(:controls, GameRoomRules.translate("Game keyboard shortcuts"),
            GameRoomRules.translate("Arrows: browse your hand or card choices."),
            GameRoomRules.translate("Enter: play the selected card or confirm the chosen opponent. After drawing, an unplayable card opens a discard confirmation; No or Escape leaves it in your hand without making a move."),
            GameRoomRules.translate("Escape: cancel the current card or opponent choice."),
            GameRoomRules.translate("Space: draw a card."),
            GameRoomRules.translate("J: after drawing, discard the selected hand card without confirmation, even if it is playable."),
            GameRoomRules.translate("Delete: choose a card to discard."),
            GameRoomRules.translate("H: read your hand."),
            GameRoomRules.translate("I: read your mileage, hazards and safeties."),
            GameRoomRules.translate("Shift+I: read every car's mileage, hazards and safeties."),
            GameRoomRules.translate("S: read scores."),
            GameRoomRules.translate("T: read whose turn it is."),
            GameRoomRules.translate("Z: find the next playable card on your turn, outside the dirty-trick window."),
            GameRoomRules.translate("Shift+Z: find the previous playable card on your turn, outside the dirty-trick window."),
            GameRoomRules.translate("Shift+C: sort by card type; press again to reverse the order."),
            GameRoomRules.translate("Shift+H: sort by distance or card value; press again to reverse the order."),
            GameRoomRules.translate("Shift+M: restore the order in which cards were received."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:aim, "C\u00EDl hry",
              "Ve h\u0159e 1000 mil \u0159\u00EDd\u00ED\u0161 auto pomoc\u00ED karet. S kartami vzd\u00E1lenosti postupuje\u0161 k c\u00EDli, zat\u00EDmco soupe\u0159\u016Fm m\u016F\u017Ee\u0161 cestu znep\u0159\u00EDjemnit p\u0159ek\u00E1\u017Ekami. K dokon\u010Den\u00ED j\u00EDzdy pot\u0159ebuje\u0161 ujet p\u0159esn\u011B 1000 mil.",
              "Za ujet\u00E9 m\u00EDle a pr\u00E9mie z\u00EDsk\u00E1v\u00E1\u0161 body, kter\u00E9 se s\u010D\u00EDtaj\u00ED z jednotliv\u00FDch kol. Vyhraje ten, kdo m\u00E1 na konci kola alespo\u0148 5000 bod\u016F a z\u00E1rove\u0148 v\u00EDc ne\u017E ostatn\u00ED. Hr\u00E1t mohou dva a\u017E osm hr\u00E1\u010D\u016F."),
            rule_section(:turn, "Co ud\u011Bl\u00E1\u0161 v tahu",
              "Do ka\u017Ed\u00E9ho kola dostane\u0161 \u0161est karet. Proch\u00E1zej je \u0161ipkami; kl\u00E1vesa H p\u0159e\u010Dte celou ruku. A\u017E bude\u0161 na \u0159ad\u011B, nejprve si mezern\u00EDkem vezmi kartu. Potom \u0161ipkami vyber kartu, kterou chce\u0161 zahr\u00E1t, a potvr\u010F ji Enterem.",
              "Kartu nemus\u00ED\u0161 zahr\u00E1t: m\u00EDsto toho m\u016F\u017Ee\u0161 jednu odhodit. Vyber ji a stiskni J. T\u00EDm tv\u016Fj tah kon\u010D\u00ED."),
            rule_section(:driving, "Rozjezd a ujet\u00E9 m\u00EDle",
              "Na za\u010D\u00E1tku kola auto stoj\u00ED. Rozjede\u0161 se zahr\u00E1n\u00EDm zelen\u00E9 a od p\u0159\u00ED\u0161t\u00EDho tahu u\u017E m\u016F\u017Ee\u0161 p\u0159id\u00E1vat karty vzd\u00E1lenosti. Ka\u017Ed\u00E1 t\u011B p\u0159ibl\u00ED\u017E\u00ED k c\u00EDli o uveden\u00FD po\u010Det mil.",
              "Na kart\u00E1ch je 25, 50, 75, 100 nebo 200 mil. Mus\u00ED\u0161 dojet p\u0159esn\u011B na 1000 mil: p\u0159i 950 m\u00EDl\u00EDch tedy nelze zahr\u00E1t 75. Za jedno kolo sm\u00ED\u0161 pou\u017E\u00EDt nejv\u00FD\u0161 dv\u011B karty po 200 m\u00EDl\u00EDch."),
            rule_section(:hazards, "P\u0159ek\u00E1\u017Eky a n\u00E1vrat na cestu",
              "Jedouc\u00ED auto m\u016F\u017Ee soupe\u0159 zastavit \u010Dervenou. Dokud stoj\u00ED\u0161, nesm\u00ED\u0161 hr\u00E1t karty vzd\u00E1lenosti; k dal\u0161\u00EDmu rozjezdu pot\u0159ebuje\u0161 novou zelenou.",
              "N\u011Bkter\u00E9 p\u0159ek\u00E1\u017Eky ale samotn\u00E1 zelen\u00E1 nevy\u0159e\u0161\u00ED. Nejd\u0159\u00EDv mus\u00ED\u0161 zahr\u00E1t kartu, kter\u00E1 odstran\u00ED p\u0159\u00ED\u010Dinu zastaven\u00ED:",
              "- P\u0159i nedostatku paliva je t\u0159eba doplnit palivo p\u0159\u00EDslu\u0161nou kartou.",
              "- Po defektu zahraj rezervn\u00ED kolo a vym\u011B\u0148 tak po\u0161kozenou pneumatiku.",
              "- N\u00E1sledky nehody odstran\u00ED\u0161 kartou Opravy.",
              "Opraven\u00E9 auto je\u0161t\u011B nejede. V dal\u0161\u00EDm tahu zahraj zelenou a teprve potom pokra\u010Duj kartami vzd\u00E1lenosti. Po defektu tedy p\u0159ijde nejd\u0159\u00EDv rezervn\u00ED kolo, pak zelen\u00E1 a a\u017E pot\u00E9 dal\u0161\u00ED m\u00EDle.",
              "T\u011Bmito \u00FAtoky lze zas\u00E1hnout jen jedouc\u00ED auto. Omezen\u00ED rychlosti se li\u0161\u00ED: sm\u00ED\u0161 ho ulo\u017Eit i stoj\u00EDc\u00EDmu autu. Nezastav\u00ED ho, ale dovol\u00ED mu hr\u00E1t pouze 25 a 50 mil. V\u011Bt\u0161\u00ED vzd\u00E1lenosti znovu zp\u0159\u00EDstupn\u00ED karta Konec omezen\u00ED rychlosti."),
            rule_section(:safeties, "Ochrann\u00E9 karty",
              "Ochrann\u00E1 karta plat\u00ED a\u017E do konce kola. Br\u00E1n\u00ED ur\u010Dit\u00E9mu \u00FAtoku a odstran\u00ED i odpov\u00EDdaj\u00EDc\u00ED p\u0159ek\u00E1\u017Eku, kter\u00E1 u\u017E na aut\u011B je. Zahraje\u0161 ji ve sv\u00E9m tahu po dobr\u00E1n\u00ED. Dostane\u0161 za ni 100 bod\u016F a dal\u0161\u00ED tah, na jeho\u017E za\u010D\u00E1tku si znovu vezme\u0161 kartu.",
              "Ve h\u0159e jsou \u010Dty\u0159i ochrann\u00E9 karty:",
              "- P\u0159\u00EDdavn\u00E1 n\u00E1dr\u017E chr\u00E1n\u00ED p\u0159ed nedostatkem paliva.",
              "- Pneumatiky odoln\u00E9 proti prop\u00EDchnut\u00ED chr\u00E1n\u00ED p\u0159ed defektem.",
              "- \u0158idi\u010Dsk\u00E9 eso chr\u00E1n\u00ED p\u0159ed nehodou i j\u00EDzdou proti sm\u011Bru.",
              "- P\u0159ednost v j\u00EDzd\u011B chr\u00E1n\u00ED p\u0159ed \u010Dervenou a omezen\u00EDm rychlosti. Nav\u00EDc umo\u017E\u0148uje rozjezd bez zelen\u00E9, a to na za\u010D\u00E1tku kola i po oprav\u011B auta.",
              "Ostatn\u00ED t\u0159i ochrann\u00E9 karty rozjezd nenahrazuj\u00ED. Po odstran\u011Bn\u00ED z\u00E1vady po\u0159\u00E1d pot\u0159ebuje\u0161 zelenou, pokud u\u017E nem\u00E1\u0161 vylo\u017Eenou P\u0159ednost v j\u00EDzd\u011B.",
              "Kl\u00E1vesou I zjist\u00ED\u0161 sv\u00E9 ujet\u00E9 m\u00EDle, p\u0159ek\u00E1\u017Eky a ochranu. Shift+I p\u0159e\u010Dte tyto \u00FAdaje u v\u0161ech hr\u00E1\u010D\u016F."),
            rule_section(:counterattack, "Okam\u017Eit\u00E1 obrana",
              "M\u00E1\u0161-li v ruce ochranu proti \u00FAtoku, kter\u00FD pr\u00E1v\u011B p\u0159i\u0161el, m\u016F\u017Ee\u0161 ji zahr\u00E1t hned, i kdy\u017E nejsi na \u0159ad\u011B. Vyber ji \u0161ipkami a stiskni Enter d\u0159\u00EDv, ne\u017E n\u011Bkdo dobere, zahraje \u010Di odhod\u00ED dal\u0161\u00ED kartu. T\u00E9to obran\u011B se \u0159\u00EDk\u00E1 coup fourr\u00E9.",
              "\u00DAtok se zru\u0161\u00ED. Jestli\u017Ee auto p\u0159ed \u00FAtokem jelo, m\u016F\u017Ee pokra\u010Dovat bez opravy i bez nov\u00E9 zelen\u00E9. K obvykl\u00FDm 100 bod\u016Fm za ochranu dostane\u0161 pr\u00E9mii 300 bod\u016F.",
              "Pokud v bal\u00ED\u010Dku je\u0161t\u011B n\u011Bco zb\u00FDv\u00E1, dostane\u0161 za zahranou ochranu n\u00E1hradn\u00ED kartu. Potom p\u0159eb\u00EDr\u00E1\u0161 tah: mezern\u00EDkem norm\u00E1ln\u011B dobere\u0161 a kartu zahraje\u0161 nebo odhod\u00ED\u0161. D\u00E1l se pokra\u010Duje od tebe, tak\u017Ee hr\u00E1\u010Di mezi \u00FAto\u010Dn\u00EDkem a tebou p\u0159ijdou o tah.",
              "Nestihne\u0161-li tuto okam\u017Eitou obranu, ochranu m\u016F\u017Ee\u0161 vylo\u017Eit pozd\u011Bji ve sv\u00E9m tahu. Pr\u00E9mie 300 bod\u016F u\u017E k n\u00ED ale nebude."),
            rule_section(:scoring, "Konec kola a body",
              "Kolo kon\u010D\u00ED dojezdem n\u011Bkter\u00E9ho auta p\u0159esn\u011B na 1000 mil. Dojde-li dob\u00EDrac\u00ED bal\u00ED\u010Dek d\u0159\u00EDv, hrajete d\u00E1l kartami v ruce. V takov\u00E9m p\u0159\u00EDpad\u011B kolo skon\u010D\u00ED tak\u00E9 ve chv\u00EDli, kdy n\u011Bkdo zahraje nebo odhod\u00ED svou posledn\u00ED kartu.",
              "Na konci kola dostane ka\u017Ed\u00FD body za svou j\u00EDzdu:",
              "- Za ka\u017Edou ujetou m\u00EDli 1 bod.",
              "- Za ka\u017Edou vylo\u017Eenou ochrannou kartu 100 bod\u016F.",
              "- Za ka\u017Edou okam\u017Eitou obranu dal\u0161\u00EDch 300 bod\u016F.",
              "Auto, kter\u00E9 dokon\u010Dilo 1000 mil, m\u016F\u017Ee z\u00EDskat i n\u00E1sleduj\u00EDc\u00ED pr\u00E9mie. Spln\u00ED-li n\u011Bkolik podm\u00EDnek, pr\u00E9mie se s\u010D\u00EDtaj\u00ED:",
              "- Za dokon\u010Den\u00ED j\u00EDzdy 300 bod\u016F.",
              "- Za dojezd p\u0159i pr\u00E1zdn\u00E9m dob\u00EDrac\u00EDm bal\u00ED\u010Dku dal\u0161\u00EDch 300 bod\u016F.",
              "- Za dojezd se v\u0161emi \u010Dty\u0159mi ochrann\u00FDmi kartami dal\u0161\u00EDch 300 bod\u016F.",
              "- Pokud \u017E\u00E1dn\u00FD soupe\u0159 neujel ani m\u00EDli, za dojezd nav\u00EDc 500 bod\u016F.",
              "P\u0159\u00ED\u0161t\u00ED kolo za\u010D\u00EDn\u00E1 nov\u00FDm rozd\u00E1n\u00EDm a j\u00EDzdou od nuly, dosavadn\u00ED body ti ale z\u016Fstanou. V\u00FDsledky p\u0159e\u010Dte S. Celkov\u00FD v\u00EDt\u011Bz mus\u00ED m\u00EDt po se\u010Dten\u00ED kola nejm\u00E9n\u011B 5000 bod\u016F a v\u00E9st s\u00E1m. P\u0159i d\u011Blen\u00E9m prvn\u00EDm m\u00EDst\u011B se hraje dal\u0161\u00ED kolo."),
            rule_section(:teams, "T\u00FDmov\u00E1 hra",
              "P\u0159ed za\u010D\u00E1tkem lze v nastaven\u00ED stolu zvolit stejn\u011B velk\u00E9 t\u00FDmy m\u00EDsto hry jednotlivc\u016F:",
              "- \u010Cty\u0159i hr\u00E1\u010Di vytvo\u0159\u00ED dv\u011B dvojice.",
              "- \u0160est hr\u00E1\u010D\u016F vytvo\u0159\u00ED dv\u011B trojice nebo t\u0159i dvojice.",
              "- Osm hr\u00E1\u010D\u016F vytvo\u0159\u00ED dva \u010Dty\u0159\u010Dlenn\u00E9 t\u00FDmy nebo \u010Dty\u0159i dvojice.",
              "T\u00FDm m\u00E1 spole\u010Dn\u00E9 auto i sk\u00F3re. Ka\u017Ed\u00FD hr\u00E1\u010D dr\u017E\u00ED vlastn\u00ED karty a hraje ve sv\u00E9m tahu, ale vzd\u00E1lenost, p\u0159ek\u00E1\u017Eky i ochrana pat\u0159\u00ED cel\u00E9mu t\u00FDmu. Spole\u010Dn\u00FD je tak\u00E9 limit dvou karet po 200 m\u00EDl\u00EDch.",
              "\u00DAto\u010D\u00ED se na auto soupe\u0159ova t\u00FDmu. Na z\u00E1sah m\u016F\u017Ee okam\u017Eit\u011B odpov\u011Bd\u011Bt ochrannou kartou kter\u00FDkoli \u010Dlen napaden\u00E9ho t\u00FDmu; pr\u00E1v\u011B on pak z\u00EDsk\u00E1 dal\u0161\u00ED tah."),
            rule_section(:variants, "Voliteln\u00E9 \u00FApravy pravidel",
              "V nastaven\u00ED stolu p\u0159ed hrou m\u016F\u017Ee\u0161 zm\u011Bnit c\u00EDlov\u00FD po\u010Det bod\u016F a zapnout tyto \u00FApravy:",
              "- Hromad\u011Bn\u00ED p\u0159ek\u00E1\u017Eek dovol\u00ED napadat stoj\u00EDc\u00ED auto r\u016Fzn\u00FDmi z\u00E1vadami. P\u0159ed rozjezdem je pak nutn\u00E9 odstranit v\u0161echny. Tut\u00E9\u017E aktivn\u00ED z\u00E1vadu nelze p\u0159idat podruh\u00E9 a \u010Dervenou lze i nad\u00E1le zahr\u00E1t jen na jedouc\u00ED auto.",
              "- Op\u011Btovn\u00E9 pou\u017Eit\u00ED odhozen\u00FDch karet z nich po vy\u010Derp\u00E1n\u00ED bal\u00ED\u010Dku vytvo\u0159\u00ED nov\u00FD dob\u00EDrac\u00ED bal\u00ED\u010Dek. Karty d\u0159\u00EDve zahran\u00E9 pro j\u00EDzdu, opravu \u010Di \u00FAtok se do n\u011Bj nevracej\u00ED.",
              "- Ochrann\u00E9 karty lze z bal\u00ED\u010Dku vy\u0159adit. Pak nen\u00ED k dispozici trval\u00E1 ochrana ani okam\u017Eit\u00E1 obrana; b\u011B\u017En\u00E9 opravy a zelen\u00E1 funguj\u00ED stejn\u011B jako dosud."),
            rule_section(:counterflow, "J\u00EDzda proti sm\u011Bru",
              "Volba Proti sm\u011Bru p\u0159id\u00E1v\u00E1 karty tohoto \u00FAtoku i jeho ukon\u010Den\u00ED. V b\u011B\u017En\u00E9m slo\u017Een\u00ED jsou \u010Dty\u0159i karty Proti sm\u011Bru a \u0161est karet Konec j\u00EDzdy proti sm\u011Bru.",
              "Zasa\u017Een\u00E9 auto se p\u0159i hran\u00ED karet vzd\u00E1lenosti vrac\u00ED: m\u00EDle se ode\u010D\u00EDtaj\u00ED, nejn\u00ED\u017Ee v\u0161ak k nule. Auto mus\u00ED m\u00EDt povolenou j\u00EDzdu a d\u00E1l pro n\u011Bj plat\u00ED omezen\u00ED rychlosti. Takto pou\u017Eit\u00FDch 200 mil se po\u010D\u00EDt\u00E1 do obvykl\u00E9ho limitu dvou t\u011Bchto karet.",
              "\u00DAtok lze zahr\u00E1t i na stoj\u00EDc\u00ED auto nebo vedle jin\u00E9 p\u0159ek\u00E1\u017Eky, ne v\u0161ak na auto, kter\u00E9 u\u017E proti sm\u011Bru jede. Spr\u00E1vn\u00FD sm\u011Br obnov\u00ED\u0161 kartou Konec j\u00EDzdy proti sm\u011Bru. Ostatn\u00ED z\u00E1vady ani omezen\u00ED rychlosti t\u00EDm nezmiz\u00ED.",
              "P\u0159ed t\u00EDmto \u00FAtokem chr\u00E1n\u00ED tak\u00E9 \u0158idi\u010Dsk\u00E9 eso. B\u011B\u017En\u00FDm vylo\u017Een\u00EDm prob\u00EDhaj\u00EDc\u00ED j\u00EDzdu proti sm\u011Bru odstran\u00ED; p\u0159i okam\u017Eit\u00E9 obran\u011B \u00FAtok zru\u0161\u00ED a p\u0159inese i pr\u00E9mii."),
            rule_section(:instant_repair, "Okam\u017Eit\u00E1 oprava",
              "Samostatnou volbou p\u0159id\u00E1\u0161 karty Okam\u017Eit\u00E1 oprava; standardn\u011B jsou v bal\u00ED\u010Dku dv\u011B. Ka\u017Ed\u00E1 vy\u0159e\u0161\u00ED jeden vybran\u00FD probl\u00E9m. Po dobr\u00E1n\u00ED ji ve sv\u00E9m tahu zahraj Enterem, \u0161ipkami vyber probl\u00E9m a Enterem volbu potvr\u010F.",
              "V\u00FDsledek z\u00E1le\u017E\u00ED na tom, co opravuje\u0161:",
              "- Odstran\u011Bn\u00ED \u010Derven\u00E9 dovol\u00ED rozjezd, pokud autu nebr\u00E1n\u00ED jin\u00E1 p\u0159ek\u00E1\u017Eka. Karta zastoup\u00ED zelenou i tehdy, kdy\u017E auto na sv\u016Fj prvn\u00ED rozjezd teprve \u010Dek\u00E1.",
              "- Po oprav\u011B paliva, pneumatiky \u010Di nehody je st\u00E1le pot\u0159eba zelen\u00E1, nem\u00E1\u0161-li P\u0159ednost v j\u00EDzd\u011B.",
              "- Zru\u0161en\u00ED omezen\u00ED rychlosti nebo j\u00EDzdy proti sm\u011Bru odstran\u00ED jen vybranou p\u0159ek\u00E1\u017Eku. Ostatn\u00ED z\u016Fst\u00E1vaj\u00ED.",
              "Okam\u017Eit\u00E1 oprava neposkytuje ochranu p\u0159ed dal\u0161\u00EDmi \u00FAtoky. Ned\u00E1v\u00E1 dal\u0161\u00ED tah ani pr\u00E9mii a nelze ji pou\u017E\u00EDt jako okam\u017Eitou obranu."),
            rule_section(:custom_deck, "Vlastn\u00ED slo\u017Een\u00ED bal\u00ED\u010Dku",
              "V nastaven\u00ED stolu lze povolit vlastn\u00ED bal\u00ED\u010Dek a zadat po\u010Dty jednotliv\u00FDch druh\u016F karet. J\u00EDzda proti sm\u011Bru, okam\u017Eit\u00E9 opravy a ochrann\u00E9 karty maj\u00ED vlastn\u00ED p\u0159ep\u00EDna\u010De: samotn\u00FD po\u010Det je do hry neza\u0159ad\u00ED.",
              "Bal\u00ED\u010Dek mus\u00ED sta\u010Dit na \u0161est karet pro ka\u017Ed\u00E9ho i na dal\u0161\u00ED hru. Krom\u011B vzd\u00E1lenost\u00ED nezapome\u0148 na karty pro rozjezd a odstra\u0148ov\u00E1n\u00ED p\u0159ek\u00E1\u017Eek. Po\u010Det karet Proti sm\u011Bru a Konec j\u00EDzdy proti sm\u011Bru lze upravit i bez vlastn\u00EDho slo\u017Een\u00ED cel\u00E9ho bal\u00ED\u010Dku."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "\u0160ipky: proch\u00E1zet karty a dostupn\u00E9 volby.",
              "Enter: zahr\u00E1t kartu a p\u0159\u00EDpadn\u011B vybrat soupe\u0159e nebo probl\u00E9m k odstran\u011Bn\u00ED; u nehrateln\u00E9 karty potvrdit odhozen\u00ED.",
              "Escape: zru\u0161it v\u00FDb\u011Br karty, soupe\u0159e nebo odhozen\u00ED.",
              "Mezern\u00EDk: dobrat kartu.",
              "J: odhodit vybranou kartu bez dal\u0161\u00EDho potvrzen\u00ED.",
              "Delete: vybrat kartu k odhozen\u00ED.",
              "H: p\u0159e\u010D\u00EDst karty v ruce.",
              "I: p\u0159e\u010D\u00EDst vlastn\u00ED vzd\u00E1lenost, p\u0159ek\u00E1\u017Eky a ochranu.",
              "Shift+I: p\u0159e\u010D\u00EDst vzd\u00E1lenost, p\u0159ek\u00E1\u017Eky a ochranu v\u0161ech aut.",
              "S: p\u0159e\u010D\u00EDst sk\u00F3re.",
              "T: ozn\u00E1mit, kdo je na tahu.",
              "Z: naj\u00EDt dal\u0161\u00ED hratelnou kartu ve vlastn\u00EDm tahu; nefunguje b\u011Bhem mo\u017Enosti okam\u017Eit\u00E9 obrany.",
              "Shift+Z: naj\u00EDt p\u0159edchoz\u00ED hratelnou kartu ve vlastn\u00EDm tahu; nefunguje b\u011Bhem mo\u017Enosti okam\u017Eit\u00E9 obrany.",
              "Shift+C: se\u0159adit karty podle druhu; opakov\u00E1n\u00EDm obr\u00E1tit po\u0159ad\u00ED.",
              "Shift+H: se\u0159adit karty podle vzd\u00E1lenosti nebo hodnoty; opakov\u00E1n\u00EDm obr\u00E1tit po\u0159ad\u00ED.",
              "Shift+M: vr\u00E1tit karty do po\u0159ad\u00ED, v n\u011Bm\u017E p\u0159i\u0161ly.")
          ]
        when "en"
          [
            rule_section(:aim, "The aim",
              "Drive your car with cards in 1000 Miles. Distance cards move you towards the finish; hazards stop or slow your opponents. Try to reach exactly 1,000 miles in each round.",
              "Miles travelled and bonuses add to a running score. At the end of a round, a player with at least 5,000 points and more points than anyone else wins the match. Two to eight people can play."),
            rule_section(:turn, "Taking a turn",
              "You receive six cards at the start of a round. Browse them with the arrows or read your hand with H. On your turn, first draw with Space, then select a card and press Enter to play it.",
              "You may discard instead of playing. Select the card and press J to discard it and end your turn."),
            rule_section(:driving, "Getting moving",
              "Your car starts stopped. Play a green light to start it; from your next turn, you can play distance cards. Each brings you that many miles closer to the finish.",
              "Distance cards are worth 25, 50, 75, 100 or 200 miles. You must finish on exactly 1,000: at 950, for example, you cannot play 75. You may use no more than two 200-mile cards in a round."),
            rule_section(:hazards, "Hazards and repairs",
              "A red light stops a moving car. You need another green light before you can play distance cards again.",
              "Three other hazards need a remedy before you can restart:",
              "- Out of gas: play a gas card to refuel.",
              "- Flat tire: play a spare tire.",
              "- Accident: play a repair card.",
              "Fixing the problem does not start the car. On a later turn, play green, then you can drive again. After a flat tire, for instance, you need the spare tire first and green afterwards.",
              "These attacks target moving cars. A speed limit can also target a stopped car: it does not prevent driving, but restricts distance plays to 25 or 50 miles. Play End of speed limit to use larger distances again."),
            rule_section(:safeties, "Safety cards",
              "A safety protects your car from particular hazards for the rest of the round. Play it after drawing on your turn. It also removes a matching hazard already affecting you. A safety earns 100 points and another turn, beginning with a new draw.",
              "There are four safeties:",
              "- Extra tank protects against running out of gas.",
              "- Puncture-proof tires protect against flat tires.",
              "- Driving ace protects against accidents and counterflow.",
              "- Right of way protects against red lights and speed limits. It also lets you start without green, both at the beginning and after repairs.",
              "The other three safeties do not themselves start the car. After removing a mechanical problem, you still need green unless you have Right of way.",
              "I reads your mileage, hazards and safeties; Shift+I reads them for every car."),
            rule_section(:counterattack, "An immediate counter",
              "If you hold the safety matching an attack you have just received, you may play it immediately, even out of turn. Select it and press Enter before anyone draws, plays or discards another card. This counter is called a coup fourr\u00E9, or dirty trick.",
              "It cancels the attack. If your car was moving beforehand, it remains able to move without a repair or another green light. You earn the usual 100 for the safety plus a 300-point bonus.",
              "You receive a replacement for the safety if cards remain to draw, then take the next turn yourself. Draw normally with Space and play or discard. Play continues from your seat afterwards, skipping anyone between the attacker and you.",
              "If you miss the immediate response, you can still play the safety on your own turn, but without the 300-point bonus."),
            rule_section(:scoring, "Round end and points",
              "A round ends when someone reaches exactly 1,000 miles. If the draw pile runs out first, keep playing the cards in your hands; the round also ends when any player plays or discards their final card.",
              "Count these points at the end of the round:",
              "- 1 point per mile travelled.",
              "- 100 for each safety played.",
              "- An extra 300 for each immediate counter.",
              "The player who reaches 1,000 also receives these bonuses, which can be combined:",
              "- 300 for finishing.",
              "- Another 300 for finishing with an empty draw pile.",
              "- Another 300 for finishing with all four safeties.",
              "- Another 500 if no opponent has travelled even one mile.",
              "A new round gives you new hands and resets the trip, but keeps your points. S reads the totals. After scoring, the player with the most points wins if they have at least 5,000. A tie for the lead means another round."),
            rule_section(:teams, "Team play",
              "The host can choose teams instead of individual play:",
              "- Four players: two pairs.",
              "- Six players: two teams of three or three pairs.",
              "- Eight players: two teams of four or four pairs.",
              "Each team shares a car and score. Everyone keeps their own hand and turn, but distance, hazards and safeties affect the team car. The two-card limit on 200-mile cards is also shared.",
              "Attacks target an opposing team's car. Any member of the attacked team may counter with a safety from their hand and take the extra turn."),
            rule_section(:variants, "Rule options",
              "Before play, the host can change the target score and these rules:",
              "- Hazard accumulation allows different mechanical problems to be played on an already stopped car. All must be removed before it can restart. An active hazard cannot be applied twice, and a red light still requires a moving car.",
              "- Recycling discards returns discarded cards to the draw pile when it empties. Cards previously used for driving, repairs or attacks do not join that new pile.",
              "- Removing safeties takes them out of the deck. There is then no permanent protection or immediate counter, but ordinary remedies and green lights still work."),
            rule_section(:counterflow, "Counterflow",
              "The optional counterflow cards make a car drive backwards. By default, this option adds four Counterflow attacks and six End of counterflow cards.",
              "An affected car subtracts the distance on a played card instead of adding it, never falling below zero. It must still be able to drive and obey any speed limit. A 200-mile card used backwards still counts towards the two-per-round limit.",
              "Counterflow can be played on a stopped car or alongside other hazards, but not on a car already affected by it. End of counterflow restores the normal direction without removing other hazards or a speed limit.",
              "Driving ace prevents counterflow, removes it when played on a normal turn, and can be used for an immediate counter and its bonus."),
            rule_section(:instant_repair, "Instant repair",
              "A separate option adds Instant repair cards, with two in the standard deck. Each removes one chosen problem. After drawing on your turn, play it with Enter, choose the problem with the arrows and confirm.",
              "Its effect depends on what you choose:",
              "- Removing a red light lets you move if nothing else blocks the car. It can also replace green when you have not yet started.",
              "- After refuelling, fixing a flat tire or repairing accident damage, you still need a green light, unless you have Right of way.",
              "- Removing a speed limit or counterflow ends only that effect; other problems remain.",
              "Instant repair is not a safety. It gives no lasting protection, extra turn or bonus, and cannot be used as an immediate counter."),
            rule_section(:custom_deck, "A custom deck",
              "Custom deck lets the host set the number of each card. Safeties, counterflow and instant repairs must still be enabled separately; entering card counts alone does not enable them.",
              "Include enough cards to deal six to everyone and keep the game moving. You need ways to start and remove hazards as well as distance cards. Counterflow and End of counterflow counts can also be adjusted without creating a whole custom deck."),
            rule_section(:controls, "Keyboard shortcuts",
              "Arrows: browse your hand or choices.",
              "Enter: play a card and, if needed, choose an opponent or problem to remove; confirm discarding an unplayable card.",
              "Escape: cancel the current card, opponent or discard choice.",
              "Space: draw.",
              "J: discard the selected card without confirmation.",
              "Delete: choose a card to discard.",
              "H: read your hand.",
              "I: read your mileage, hazards and safeties.",
              "Shift+I: read mileage, hazards and safeties for all cars.",
              "S: read scores.",
              "T: read whose turn it is.",
              "Z: find the next playable card on your turn; unavailable while you can make an immediate counter.",
              "Shift+Z: find the previous playable card on your turn; unavailable while you can make an immediate counter.",
              "Shift+C: sort by card type; repeat to reverse.",
              "Shift+H: sort by distance or value; repeat to reverse.",
              "Shift+M: restore received order.")
          ]
        when "es"
          [
            rule_section(:aim, "Objetivo",
              "En 1000 millas conduces con cartas. Las de distancia te acercan a la meta; las de peligro frenan o detienen a los rivales. En cada ronda intentas recorrer exactamente 1000 millas.",
              "Las millas y las bonificaciones se convierten en puntos, que se acumulan entre rondas. Gana quien, al terminar una ronda, tenga al menos 5000 puntos y m\u00E1s que cualquier rival. Pueden jugar de dos a ocho personas."),
            rule_section(:turn, "Tu turno",
              "Empiezas la ronda con seis cartas. Rec\u00F3rrelas con las flechas o escucha la mano completa con H. En cada turno, roba primero una carta con Espacio. Despu\u00E9s elige una carta de tu mano con las flechas y ju\u00E9gala con Enter.",
              "En vez de jugar puedes descartar una carta. Selecci\u00F3nala y pulsa J; con eso termina tu turno."),
            rule_section(:driving, "Arrancar y recorrer millas",
              "Tu coche empieza detenido. Juega \u00ABSem\u00E1foro verde\u00BB para arrancar; a partir del turno siguiente podr\u00E1s jugar cartas de distancia. Cada una te acerca a la meta las millas que indica.",
              "Hay cartas de 25, 50, 75, 100 y 200 millas. Debes llegar exactamente a 1000: con 950 no puedes jugar 75. En una misma ronda puedes usar como m\u00E1ximo dos cartas de 200."),
            rule_section(:hazards, "Peligros y c\u00F3mo volver a circular",
              "Un rival puede detener un coche en marcha con \u00ABSem\u00E1foro rojo\u00BB. Necesitar\u00E1s otro verde para arrancar. Mientras est\u00E9s detenido no puedes jugar cartas de distancia.",
              "Otros ataques requieren resolver primero el problema con una carta adecuada:",
              "- \u00ABSin combustible\u00BB deja el dep\u00F3sito vac\u00EDo. Juega una carta de combustible para llenarlo.",
              "- \u00ABPinchazo\u00BB exige una \u00ABRueda de repuesto\u00BB para cambiar el neum\u00E1tico.",
              "- Tras un \u00ABAccidente\u00BB, juega \u00ABReparaciones\u00BB.",
              "Resolver el problema no pone el coche en marcha. En un turno posterior necesitas jugar verde antes de volver a usar distancia. Tras un pinchazo, por ejemplo, primero juegas la rueda de repuesto y despu\u00E9s el sem\u00E1foro verde.",
              "Esos ataques solo se lanzan contra coches en marcha. \u00ABL\u00EDmite de velocidad\u00BB es distinto: tambi\u00E9n puede afectar a uno detenido. No obliga a parar, pero solo deja jugar distancias de 25 y 50. Juega \u00ABFin del l\u00EDmite de velocidad\u00BB para volver a usar las mayores."),
            rule_section(:safeties, "Protecciones permanentes",
              "Una protecci\u00F3n evita ciertos ataques durante el resto de la ronda. Puedes jugarla en tu turno despu\u00E9s de robar. Tambi\u00E9n elimina el peligro correspondiente si ya lo sufres. Cada protecci\u00F3n jugada vale 100 puntos y te da otro turno, que empiezas robando una carta.",
              "Hay cuatro protecciones:",
              "- \u00ABDep\u00F3sito adicional\u00BB protege contra \u00ABSin combustible\u00BB.",
              "- \u00ABNeum\u00E1ticos antipinchazos\u00BB protege contra \u00ABPinchazo\u00BB.",
              "- \u00ABAs del volante\u00BB protege contra accidentes y circulaci\u00F3n en sentido contrario.",
              "- \u00ABPrioridad de paso\u00BB protege contra el sem\u00E1foro rojo y el l\u00EDmite de velocidad. Adem\u00E1s permite arrancar sin verde, tanto al principio de la ronda como despu\u00E9s de reparar el coche.",
              "Las otras tres protecciones no permiten arrancar por s\u00ED solas. Tras solucionar la aver\u00EDa sigue haciendo falta un verde, salvo que ya tengas prioridad de paso.",
              "I consulta tu distancia, peligros y protecciones; Shift+I consulta los de todos los coches."),
            rule_section(:counterattack, "Responder a un ataque al instante",
              "Si tienes en la mano la protecci\u00F3n contra un ataque que acabas de recibir, puedes jugarla inmediatamente, incluso fuera de turno. Selecci\u00F3nala con las flechas y pulsa Enter antes de que alguien robe, juegue o descarte otra carta. Esta respuesta se llama coup fourr\u00E9.",
              "El ataque queda anulado. Si ibas en marcha, sigues circulando sin reparar ni volver a jugar verde. Adem\u00E1s de los 100 puntos de la protecci\u00F3n, ganas una bonificaci\u00F3n de 300.",
              "Recibes una carta para reponer la protecci\u00F3n jugada, si a\u00FAn queda mazo. Despu\u00E9s tomas el turno: roba normalmente con Espacio y juega o descarta. El orden contin\u00FAa desde ti, salt\u00E1ndose a quienes estuvieran entre el atacante y t\u00FA.",
              "Si no respondes a tiempo, puedes usar la protecci\u00F3n en tu turno, pero ya no obtienes los 300 puntos de bonificaci\u00F3n."),
            rule_section(:scoring, "Fin de ronda y puntos",
              "La ronda termina cuando alguien llega exactamente a 1000 millas. Si se agota el mazo, se sigue con las cartas que queden en las manos; la ronda tambi\u00E9n termina cuando un jugador juega o descarta su \u00FAltima carta.",
              "Cada jugador recibe estos puntos:",
              "- 1 por cada milla recorrida.",
              "- 100 por cada protecci\u00F3n jugada.",
              "- 300 adicionales por cada coup fourr\u00E9.",
              "Quien llega a 1000 millas recibe adem\u00E1s estas bonificaciones, que pueden acumularse:",
              "- 300 por completar el recorrido.",
              "- Otros 300 por terminar cuando el mazo ya est\u00E1 vac\u00EDo.",
              "- Otros 300 por terminar con las cuatro protecciones.",
              "- Otros 500 si ning\u00FAn rival ha recorrido una sola milla.",
              "En la ronda siguiente se reparten cartas nuevas y todos vuelven al inicio de la ruta, conservando los puntos. S consulta los resultados. Para ganar la partida debes terminar una ronda con al menos 5000 puntos y en solitario a la cabeza. Si hay empate en el primer puesto, se juega otra ronda."),
            rule_section(:teams, "Juego por equipos",
              "Antes de jugar puedes elegir equipos de igual tama\u00F1o:",
              "- Cuatro personas: dos parejas.",
              "- Seis personas: dos equipos de tres o tres parejas.",
              "- Ocho personas: dos equipos de cuatro o cuatro parejas.",
              "Cada equipo conduce un solo coche y comparte puntuaci\u00F3n. Cada miembro conserva su mano y su turno, pero las distancias, los peligros y las protecciones afectan al coche com\u00FAn. El m\u00E1ximo de dos cartas de 200 millas tambi\u00E9n se comparte.",
              "Los ataques se dirigen al coche de otro equipo. Cualquier miembro del equipo atacado puede responder con una protecci\u00F3n de su mano y tomar el turno adicional."),
            rule_section(:variants, "Variantes",
              "Los ajustes de la mesa permiten cambiar la meta de puntos y activar estas reglas:",
              "- Acumular peligros permite a\u00F1adir distintas aver\u00EDas a un coche ya detenido. Debe resolverlas todas antes de arrancar. No puede repetirse una aver\u00EDa que siga activa, y el rojo sigue requiriendo un coche en marcha.",
              "- Reutilizar descartes crea un nuevo mazo con las cartas descartadas cuando se acaba el anterior. No recupera las cartas que se usaron para avanzar, reparar o atacar.",
              "- Puedes quitar las protecciones del mazo. No habr\u00E1 protecci\u00F3n permanente ni coup fourr\u00E9; las reparaciones normales y el verde seguir\u00E1n funcionando igual."),
            rule_section(:counterflow, "Sentido contrario",
              "Esta opci\u00F3n a\u00F1ade cartas de ataque \u00ABSentido contrario\u00BB y cartas \u00ABFin del sentido contrario\u00BB. Las cantidades iniciales son cuatro y seis, respectivamente.",
              "Un coche afectado retrocede: sus cartas de distancia restan millas, sin bajar de cero. Para jugarlas sigue necesitando estar en condiciones de circular y respetar el l\u00EDmite de velocidad. Una carta de 200 usada para retroceder cuenta dentro del m\u00E1ximo habitual de dos.",
              "El ataque puede aplicarse a un coche detenido y coexistir con otros peligros, pero no repetirse mientras siga activo. \u00ABFin del sentido contrario\u00BB permite volver a avanzar; no quita las otras aver\u00EDas ni el l\u00EDmite de velocidad.",
              "\u00ABAs del volante\u00BB protege tambi\u00E9n contra este ataque y lo elimina al jugarse normalmente. Puede usarse de inmediato como coup fourr\u00E9, con su bonificaci\u00F3n."),
            rule_section(:instant_repair, "Reparaci\u00F3n instant\u00E1nea",
              "Otra opci\u00F3n a\u00F1ade cartas de \u00ABReparaci\u00F3n instant\u00E1nea\u00BB; su cantidad habitual es dos. Cada una resuelve un problema a tu elecci\u00F3n. Despu\u00E9s de robar en tu turno, ju\u00E9gala con Enter, elige el problema con las flechas y confirma con Enter.",
              "El resultado depende de lo que repares:",
              "- Quitar un rojo permite arrancar si ning\u00FAn otro peligro te detiene. Tambi\u00E9n puede sustituir al verde cuando el coche a\u00FAn espera para arrancar.",
              "- Resolver la falta de combustible, un pinchazo o un accidente sigue exigiendo un verde despu\u00E9s, salvo que tengas prioridad de paso.",
              "- Quitar el l\u00EDmite de velocidad o el sentido contrario solo termina ese efecto. Los dem\u00E1s peligros permanecen.",
              "No es una protecci\u00F3n: no evita ataques futuros, no da un turno adicional ni bonificaciones y no sirve para hacer un coup fourr\u00E9."),
            rule_section(:custom_deck, "Personalizar el mazo",
              "Puedes activar un mazo personalizado y elegir cu\u00E1ntas cartas habr\u00E1 de cada tipo. Las protecciones, el sentido contrario y las reparaciones instant\u00E1neas se activan por separado: introducir su cantidad no basta para incluirlas.",
