          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u00AB1000 \u043C\u0438\u043B\u044C\u00BB \u043E\u0442 \u0434\u0432\u0443\u0445 \u0434\u043E \u0432\u043E\u0441\u044C\u043C\u0438 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0432 \u0430\u0432\u0442\u043E\u043C\u043E\u0431\u0438\u043B\u044C\u043D\u0443\u044E \u0433\u043E\u043D\u043A\u0443. \u041C\u0430\u0448\u0438\u043D\u043E\u0439 \u0432\u044B \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0435 \u0441 \u043F\u043E\u043C\u043E\u0449\u044C\u044E \u043A\u0430\u0440\u0442: \u043E\u0434\u043D\u0438 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442 \u043F\u0440\u043E\u0435\u0445\u0430\u0442\u044C \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043C\u0438\u043B\u044C, \u0434\u0440\u0443\u0433\u0438\u0435 \u043C\u0435\u0448\u0430\u044E\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C. \u0427\u0442\u043E\u0431\u044B \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u044C \u043C\u0430\u0440\u0448\u0440\u0443\u0442, \u043D\u0443\u0436\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u0440\u043E\u0432\u043D\u043E 1000 \u043C\u0438\u043B\u044C.",
              "\u0417\u0430 \u043F\u0440\u043E\u0439\u0434\u0435\u043D\u043D\u044B\u0439 \u043F\u0443\u0442\u044C \u0438 \u0440\u0430\u0437\u043B\u0438\u0447\u043D\u044B\u0435 \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u044F \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u043E\u0447\u043A\u0438. \u041E\u043D\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u043E\u0442 \u0440\u0430\u0443\u043D\u0434\u0430 \u043A \u0440\u0430\u0443\u043D\u0434\u0443. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u043F\u043E \u0438\u0442\u043E\u0433\u0430\u043C \u043E\u0447\u0435\u0440\u0435\u0434\u043D\u043E\u0433\u043E \u0440\u0430\u0443\u043D\u0434\u0430 \u043D\u0430\u0431\u0435\u0440\u0451\u0442 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 5000 \u043E\u0447\u043A\u043E\u0432 \u0438 \u043E\u043F\u0435\u0440\u0435\u0434\u0438\u0442 \u0432\u0441\u0435\u0445 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445."),
            rule_section(:turn, "\u041A\u0430\u043A \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0445\u043E\u0434",
              "\u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u0443 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043F\u043E \u0448\u0435\u0441\u0442\u044C \u043A\u0430\u0440\u0442. \u041F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0438\u0445 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438\u043B\u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 H, \u0447\u0442\u043E\u0431\u044B \u0443\u0441\u043B\u044B\u0448\u0430\u0442\u044C \u0432\u0441\u044E \u0440\u0443\u043A\u0443. \u041A\u043E\u0433\u0434\u0430 \u043D\u0430\u0441\u0442\u0443\u043F\u0438\u0442 \u0432\u0430\u0448 \u0445\u043E\u0434, \u0432\u043E\u0437\u044C\u043C\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 \u041F\u0440\u043E\u0431\u0435\u043B. \u0417\u0430\u0442\u0435\u043C \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043A\u0430\u0440\u0442\u0443, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u0445\u043E\u0442\u0438\u0442\u0435 \u0441\u044B\u0433\u0440\u0430\u0442\u044C, \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter.",
              "\u0412\u043C\u0435\u0441\u0442\u043E \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430 \u043C\u043E\u0436\u043D\u043E \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043B\u044E\u0431\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0441 \u0440\u0443\u043A\u0438. \u0414\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0451 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 J. \u041F\u043E\u0441\u043B\u0435 \u0441\u0431\u0440\u043E\u0441\u0430 \u0445\u043E\u0434 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0434\u0430\u043B\u044C\u0448\u0435."),
            rule_section(:driving, "\u041D\u0430\u0447\u0430\u043B\u043E \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u0438 \u043A\u0430\u0440\u0442\u044B \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u044F",
              "\u041F\u043E\u043D\u0430\u0447\u0430\u043B\u0443 \u0432\u0430\u0448\u0430 \u043C\u0430\u0448\u0438\u043D\u0430 \u0441\u0442\u043E\u0438\u0442. \u0421\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u00AB\u0417\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442\u00BB, \u0447\u0442\u043E\u0431\u044B \u0442\u0440\u043E\u043D\u0443\u0442\u044C\u0441\u044F \u0441 \u043C\u0435\u0441\u0442\u0430. \u0421\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0445\u043E\u0434\u0430 \u0432\u044B \u0441\u043C\u043E\u0436\u0435\u0442\u0435 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u044F: \u043A\u0430\u0436\u0434\u0430\u044F \u043F\u0440\u0438\u0431\u043B\u0438\u0436\u0430\u0435\u0442 \u0432\u0430\u0441 \u043A \u0444\u0438\u043D\u0438\u0448\u0443 \u043D\u0430 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u043C\u0438\u043B\u044C.",
              "\u0412 \u043A\u043E\u043B\u043E\u0434\u0435 \u0435\u0441\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043D\u0430 25, 50, 75, 100 \u0438 200 \u043C\u0438\u043B\u044C. \u041F\u0440\u0435\u0432\u044B\u0448\u0430\u0442\u044C 1000 \u043D\u0435\u043B\u044C\u0437\u044F: \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u0440\u043E\u0439\u0434\u044F 950 \u043C\u0438\u043B\u044C, \u0432\u044B \u0443\u0436\u0435 \u043D\u0435 \u0441\u043C\u043E\u0436\u0435\u0442\u0435 \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u043D\u0430 75. \u0417\u0430 \u043E\u0434\u0438\u043D \u0440\u0430\u0443\u043D\u0434 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u0434\u0432\u0443\u0445 \u043A\u0430\u0440\u0442 \u043D\u0430 200 \u043C\u0438\u043B\u044C."),
            rule_section(:hazards, "\u041F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u044F \u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0432 \u0433\u043E\u043D\u043A\u0443",
              "\u0421\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043C\u043E\u0436\u0435\u0442 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0434\u0432\u0438\u0436\u0443\u0449\u0443\u044E\u0441\u044F \u043C\u0430\u0448\u0438\u043D\u0443 \u043A\u0430\u0440\u0442\u043E\u0439 \u00AB\u041A\u0440\u0430\u0441\u043D\u044B\u0439 \u0441\u0432\u0435\u0442\u00BB. \u041F\u043E\u043A\u0430 \u043C\u0430\u0448\u0438\u043D\u0430 \u0441\u0442\u043E\u0438\u0442, \u043A\u0430\u0440\u0442\u044B \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u044F \u0438\u0433\u0440\u0430\u0442\u044C \u043D\u0435\u043B\u044C\u0437\u044F. \u0427\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u043F\u0443\u0442\u044C \u043F\u043E\u0441\u043B\u0435 \u043A\u0440\u0430\u0441\u043D\u043E\u0433\u043E \u0441\u0432\u0435\u0442\u0430, \u043D\u0443\u0436\u0435\u043D \u043D\u043E\u0432\u044B\u0439 \u0437\u0435\u043B\u0451\u043D\u044B\u0439.",
              "\u041E\u0434\u043D\u0430\u043A\u043E \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442 \u043F\u043E\u043C\u043E\u0433\u0430\u0435\u0442 \u043D\u0435 \u0432\u0441\u0435\u0433\u0434\u0430. \u041F\u043E\u0441\u043B\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445 \u0442\u0440\u0451\u0445 \u0430\u0442\u0430\u043A \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0440\u0438\u0434\u0451\u0442\u0441\u044F \u0443\u0441\u0442\u0440\u0430\u043D\u0438\u0442\u044C \u0441\u0430\u043C\u0443 \u043D\u0435\u0438\u0441\u043F\u0440\u0430\u0432\u043D\u043E\u0441\u0442\u044C:",
              "- \u00AB\u041D\u0435\u0445\u0432\u0430\u0442\u043A\u0430 \u0442\u043E\u043F\u043B\u0438\u0432\u0430\u00BB \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u0432\u0430\u0441 \u0431\u0435\u0437 \u0431\u0435\u043D\u0437\u0438\u043D\u0430. \u0421\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u00AB\u0422\u043E\u043F\u043B\u0438\u0432\u043E\u00BB, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u043F\u0440\u0430\u0432\u0438\u0442\u044C\u0441\u044F.",
              "- \u041F\u043E\u0441\u043B\u0435 \u00AB\u041F\u0440\u043E\u043A\u043E\u043B\u0430 \u0448\u0438\u043D\u044B\u00BB \u043D\u0443\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u00AB\u0417\u0430\u043F\u0430\u0441\u043D\u043E\u0435 \u043A\u043E\u043B\u0435\u0441\u043E\u00BB.",
              "- \u041F\u043E\u0441\u043B\u0435\u0434\u0441\u0442\u0432\u0438\u044F \u00AB\u0410\u0432\u0430\u0440\u0438\u0438\u00BB \u0443\u0441\u0442\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u043A\u0430\u0440\u0442\u043E\u0439 \u00AB\u0420\u0435\u043C\u043E\u043D\u0442\u00BB.",
              "\u0418\u0441\u043F\u0440\u0430\u0432\u043D\u0430\u044F \u043C\u0430\u0448\u0438\u043D\u0430 \u0435\u0449\u0451 \u043D\u0435 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043E \u043C\u043E\u0436\u043D\u043E \u0435\u0445\u0430\u0442\u044C. \u0423\u0441\u0442\u0440\u0430\u043D\u0438\u0432 \u043D\u0435\u0438\u0441\u043F\u0440\u0430\u0432\u043D\u043E\u0441\u0442\u044C, \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0445\u043E\u0434 \u0441\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442; \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u0441\u043D\u043E\u0432\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u043A\u0430\u0440\u0442\u044B \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u044F. \u0422\u0430\u043A, \u043F\u043E\u0441\u043B\u0435 \u043F\u0440\u043E\u043A\u043E\u043B\u0430 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u043E\u043D\u0430\u0434\u043E\u0431\u0438\u0442\u0441\u044F \u0437\u0430\u043F\u0430\u0441\u043D\u043E\u0435 \u043A\u043E\u043B\u0435\u0441\u043E, \u0430 \u0437\u0430\u0442\u0435\u043C \u2014 \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442.",
              "\u0412\u0441\u0435 \u043F\u0435\u0440\u0435\u0447\u0438\u0441\u043B\u0435\u043D\u043D\u044B\u0435 \u0430\u0442\u0430\u043A\u0438 \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0430 \u0434\u0432\u0438\u0436\u0443\u0449\u0443\u044E\u0441\u044F \u043C\u0430\u0448\u0438\u043D\u0443. \u00AB\u041E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u0438\u00BB \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0438 \u043D\u0430 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0432\u0448\u0443\u044E\u0441\u044F: \u043E\u043D\u043E \u043D\u0435 \u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u0432\u0430\u0441, \u043D\u043E \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043B\u0438\u0448\u044C \u043A\u0430\u0440\u0442\u044B \u043D\u0430 25 \u0438 50 \u043C\u0438\u043B\u044C. \u0421\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u00AB\u041A\u043E\u043D\u0435\u0446 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u0438\u00BB, \u0447\u0442\u043E\u0431\u044B \u0441\u043D\u043E\u0432\u0430 \u043F\u0440\u043E\u0435\u0437\u0436\u0430\u0442\u044C \u0431\u043E\u043B\u0435\u0435 \u0434\u043B\u0438\u043D\u043D\u044B\u0435 \u043E\u0442\u0440\u0435\u0437\u043A\u0438."),
            rule_section(:safeties, "\u0417\u0430\u0449\u0438\u0442\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B",
              "\u0417\u0430\u0449\u0438\u0442\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0440\u0430\u0443\u043D\u0434\u0430: \u043E\u043D\u0430 \u043D\u0435 \u0434\u0430\u0451\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u0430\u0442\u0430\u043A\u0438 \u0438 \u0441\u043D\u0438\u043C\u0430\u0435\u0442 \u0442\u0430\u043A\u0443\u044E \u0430\u0442\u0430\u043A\u0443, \u0435\u0441\u043B\u0438 \u0442\u0430 \u0443\u0436\u0435 \u043C\u0435\u0448\u0430\u0435\u0442 \u0432\u0430\u043C. \u0417\u0430\u0449\u0438\u0442\u0443 \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u043F\u043E\u0441\u043B\u0435 \u0432\u0437\u044F\u0442\u0438\u044F \u043A\u0430\u0440\u0442\u044B. \u0417\u0430 \u043D\u0435\u0451 \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u0435\u0442\u0441\u044F 100 \u043E\u0447\u043A\u043E\u0432, \u0430 \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 \u0435\u0449\u0451 \u043E\u0434\u0438\u043D \u0445\u043E\u0434 \u0438 \u0432\u043D\u043E\u0432\u044C \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0435 \u0441\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u043A\u0430\u0440\u0442\u044B.",
              "\u0412 \u0438\u0433\u0440\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0432\u0438\u0434\u0430 \u0437\u0430\u0449\u0438\u0442\u044B:",
              "- \u00AB\u0414\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0431\u0430\u043A\u00BB \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043E\u0442 \u043D\u0435\u0445\u0432\u0430\u0442\u043A\u0438 \u0442\u043E\u043F\u043B\u0438\u0432\u0430.",
              "- \u00AB\u041D\u0435\u043F\u0440\u043E\u043A\u0430\u043B\u044B\u0432\u0430\u0435\u043C\u044B\u0435 \u0448\u0438\u043D\u044B\u00BB \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0442 \u043E\u0442 \u043F\u0440\u043E\u043A\u043E\u043B\u0430.",
              "- \u00AB\u0410\u0441 \u0432\u043E\u0436\u0434\u0435\u043D\u0438\u044F\u00BB \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043E\u0442 \u0430\u0432\u0430\u0440\u0438\u0439 \u0438 \u0432\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0433\u043E \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F.",
              "- \u00AB\u041F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E \u043F\u0440\u043E\u0435\u0437\u0434\u0430\u00BB \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043E\u0442 \u043A\u0440\u0430\u0441\u043D\u043E\u0433\u043E \u0441\u0432\u0435\u0442\u0430 \u0438 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u0438. \u041A\u0440\u043E\u043C\u0435 \u0442\u043E\u0433\u043E, \u0441 \u044D\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u043E\u0439 \u043C\u043E\u0436\u043D\u043E \u0442\u0440\u043E\u0433\u0430\u0442\u044C\u0441\u044F \u0431\u0435\u0437 \u0437\u0435\u043B\u0451\u043D\u043E\u0433\u043E \u0441\u0432\u0435\u0442\u0430 \u2014 \u0438 \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u0440\u0430\u0443\u043D\u0434\u0430, \u0438 \u043F\u043E\u0441\u043B\u0435 \u0443\u0441\u0442\u0440\u0430\u043D\u0435\u043D\u0438\u044F \u043D\u0435\u0438\u0441\u043F\u0440\u0430\u0432\u043D\u043E\u0441\u0442\u0438.",
              "\u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0442\u0440\u0438 \u0437\u0430\u0449\u0438\u0442\u044B \u043D\u0435 \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0442 \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442. \u0423\u0441\u0442\u0440\u0430\u043D\u0438\u0432 \u0441 \u0438\u0445 \u043F\u043E\u043C\u043E\u0449\u044C\u044E \u043D\u0435\u0438\u0441\u043F\u0440\u0430\u0432\u043D\u043E\u0441\u0442\u044C, \u0441\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442, \u0435\u0441\u043B\u0438 \u0443 \u0432\u0430\u0441 \u0435\u0449\u0451 \u043D\u0435\u0442 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u043F\u0440\u043E\u0435\u0437\u0434\u0430.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 I \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0432\u0430\u0448 \u043F\u0440\u043E\u0431\u0435\u0433, \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u044F \u0438 \u0437\u0430\u0449\u0438\u0442\u044B. \u0427\u0442\u043E\u0431\u044B \u0443\u0437\u043D\u0430\u0442\u044C \u0442\u043E \u0436\u0435 \u0441\u0430\u043C\u043E\u0435 \u043E\u0431\u043E \u0432\u0441\u0435\u0445 \u043C\u0430\u0448\u0438\u043D\u0430\u0445, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Shift+I."),
            rule_section(:counterattack, "\u041A\u043E\u043D\u0442\u0440\u0430\u0442\u0430\u043A\u0430",
              "\u0415\u0441\u043B\u0438 \u0432\u0430\u0441 \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0442\u043E \u0430\u0442\u0430\u043A\u043E\u0432\u0430\u043B\u0438, \u0430 \u0432 \u0440\u0443\u043A\u0435 \u0435\u0441\u0442\u044C \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0430\u044F \u0437\u0430\u0449\u0438\u0442\u0430, \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u0432\u0435\u0442\u0438\u0442\u044C \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E, \u0434\u0430\u0436\u0435 \u0432\u043D\u0435 \u0441\u0432\u043E\u0435\u0439 \u043E\u0447\u0435\u0440\u0435\u0434\u0438. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0437\u0430\u0449\u0438\u0442\u043D\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0423\u0441\u043F\u0435\u0442\u044C \u043D\u0443\u0436\u043D\u043E \u0434\u043E \u0442\u043E\u0433\u043E, \u043A\u0430\u043A \u043A\u0442\u043E-\u043B\u0438\u0431\u043E \u0432\u043E\u0437\u044C\u043C\u0451\u0442, \u0441\u044B\u0433\u0440\u0430\u0435\u0442 \u0438\u043B\u0438 \u0441\u0431\u0440\u043E\u0441\u0438\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u043A\u0430\u0440\u0442\u0443. \u042D\u0442\u043E\u0442 \u043F\u0440\u0438\u0451\u043C \u043D\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F coup fourr\u00E9, \u0438\u043B\u0438 \u043A\u043E\u043D\u0442\u0440\u0430\u0442\u0430\u043A\u043E\u0439.",
              "\u041A\u043E\u043D\u0442\u0440\u0430\u0442\u0430\u043A\u0430 \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u043D\u0430\u043F\u0430\u0434\u0435\u043D\u0438\u0435. \u0415\u0441\u043B\u0438 \u0434\u043E \u043D\u0435\u0433\u043E \u043C\u0430\u0448\u0438\u043D\u0430 \u0435\u0445\u0430\u043B\u0430, \u0435\u0439 \u043D\u0435 \u043F\u043E\u043D\u0430\u0434\u043E\u0431\u044F\u0442\u0441\u044F \u043D\u0438 \u0440\u0435\u043C\u043E\u043D\u0442, \u043D\u0438 \u043D\u043E\u0432\u044B\u0439 \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442. \u0417\u0430 \u0441\u0432\u043E\u0435\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442 \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 300 \u043E\u0447\u043A\u043E\u0432 \u0441\u0432\u0435\u0440\u0445 \u043E\u0431\u044B\u0447\u043D\u044B\u0445 100 \u0437\u0430 \u0437\u0430\u0449\u0438\u0442\u0443.",
              "\u0412\u0437\u0430\u043C\u0435\u043D \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u043E\u0439 \u0437\u0430\u0449\u0438\u0442\u044B \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 \u043A\u0430\u0440\u0442\u0443, \u0435\u0441\u043B\u0438 \u0432 \u043A\u043E\u043B\u043E\u0434\u0435 \u0435\u0449\u0451 \u0447\u0442\u043E-\u0442\u043E \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0432\u0430\u0448 \u0445\u043E\u0434: \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u041F\u0440\u043E\u0431\u0435\u043B \u0434\u043B\u044F \u043E\u0431\u044B\u0447\u043D\u043E\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u043A\u0430\u0440\u0442\u044B \u0438 \u0441\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u0438\u043B\u0438 \u0441\u0431\u0440\u043E\u0441\u044C\u0442\u0435 \u043E\u0434\u043D\u0443. \u0417\u0430\u0442\u0435\u043C \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u0441\u044F \u043E\u0442 \u0432\u0430\u0441, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0438 \u043C\u0435\u0436\u0434\u0443 \u043D\u0430\u043F\u0430\u0434\u0430\u0432\u0448\u0438\u043C \u0438 \u0432\u0430\u043C\u0438 \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u044F\u0442 \u0445\u043E\u0434.",
              "\u0415\u0441\u043B\u0438 \u0432\u0440\u0435\u043C\u044F \u0434\u043B\u044F \u043E\u0442\u0432\u0435\u0442\u0430 \u0443\u0436\u0435 \u0443\u043F\u0443\u0449\u0435\u043D\u043E, \u0437\u0430\u0449\u0438\u0442\u0443 \u0432\u0441\u0451 \u0435\u0449\u0451 \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434. \u041E\u043D\u0430 \u0441\u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u043A\u0430\u043A \u043E\u0431\u044B\u0447\u043D\u043E, \u043D\u043E \u043F\u0440\u0435\u043C\u0438\u0438 \u0432 300 \u043E\u0447\u043A\u043E\u0432 \u043D\u0435 \u0431\u0443\u0434\u0435\u0442."),
            rule_section(:scoring, "\u041A\u043E\u043D\u0435\u0446 \u0440\u0430\u0443\u043D\u0434\u0430 \u0438 \u043F\u043E\u0434\u0441\u0447\u0451\u0442 \u043E\u0447\u043A\u043E\u0432",
              "\u0420\u0430\u0443\u043D\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F, \u043A\u0430\u043A \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u043D\u0430 \u0438\u0437 \u043C\u0430\u0448\u0438\u043D \u043F\u0440\u043E\u0435\u0434\u0435\u0442 \u0440\u043E\u0432\u043D\u043E 1000 \u043C\u0438\u043B\u044C. \u0415\u0441\u043B\u0438 \u043A\u043E\u043B\u043E\u0434\u0430 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u043B\u0430\u0441\u044C \u0440\u0430\u043D\u044C\u0448\u0435, \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0439\u0442\u0435 \u0438\u0433\u0440\u0430\u0442\u044C \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u043C\u0438\u0441\u044F \u043A\u0430\u0440\u0442\u0430\u043C\u0438. \u0412 \u044D\u0442\u043E\u043C \u0441\u043B\u0443\u0447\u0430\u0435 \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F \u0442\u0430\u043A\u0436\u0435, \u043A\u043E\u0433\u0434\u0430 \u043A\u0442\u043E-\u043D\u0438\u0431\u0443\u0434\u044C \u0441\u044B\u0433\u0440\u0430\u0435\u0442 \u0438\u043B\u0438 \u0441\u0431\u0440\u043E\u0441\u0438\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u043A\u0430\u0440\u0442\u0443 \u0441 \u0440\u0443\u043A\u0438.",
              "\u0412 \u043A\u043E\u043D\u0446\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0447\u043A\u0438 \u0437\u0430 \u0441\u0432\u043E\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442:",
              "- \u041F\u043E 1 \u043E\u0447\u043A\u0443 \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u043F\u0440\u043E\u0439\u0434\u0435\u043D\u043D\u0443\u044E \u043C\u0438\u043B\u044E.",
              "- \u041F\u043E 100 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u0443\u044E \u0437\u0430\u0449\u0438\u0442\u0443.",
              "- \u0415\u0449\u0451 \u043F\u043E 300 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u043A\u043E\u043D\u0442\u0440\u0430\u0442\u0430\u043A\u0443.",
              "\u0422\u043E\u043C\u0443, \u043A\u0442\u043E \u0434\u043E\u0441\u0442\u0438\u0433 1000 \u043C\u0438\u043B\u044C, \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043F\u0440\u0435\u043C\u0438\u0438. \u0415\u0441\u043B\u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u044B \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0443\u0441\u043B\u043E\u0432\u0438\u0439, \u043F\u0440\u0435\u043C\u0438\u0438 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F:",
              "- 300 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u043C\u0430\u0440\u0448\u0440\u0443\u0442\u0430.",
              "- \u0415\u0449\u0451 300 \u043E\u0447\u043A\u043E\u0432, \u0435\u0441\u043B\u0438 \u043A \u043C\u043E\u043C\u0435\u043D\u0442\u0443 \u0444\u0438\u043D\u0438\u0448\u0430 \u043A\u043E\u043B\u043E\u0434\u0430 \u043F\u0443\u0441\u0442\u0430.",
              "- \u0415\u0449\u0451 300 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0444\u0438\u043D\u0438\u0448 \u0441\u043E \u0432\u0441\u0435\u043C\u0438 \u0447\u0435\u0442\u044B\u0440\u044C\u043C\u044F \u0437\u0430\u0449\u0438\u0442\u0430\u043C\u0438.",
              "- \u0415\u0449\u0451 500 \u043E\u0447\u043A\u043E\u0432, \u0435\u0441\u043B\u0438 \u043D\u0438 \u043E\u0434\u0438\u043D \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043D\u0435 \u043F\u0440\u043E\u0435\u0445\u0430\u043B \u043D\u0438 \u043C\u0438\u043B\u0438.",
              "\u0412 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C \u0440\u0430\u0443\u043D\u0434\u0435 \u0432\u0441\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043D\u043E\u0432\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442 \u043F\u0443\u0442\u044C \u0441 \u043D\u0443\u043B\u044F, \u0430 \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043E\u0447\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 S, \u0447\u0442\u043E\u0431\u044B \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u0447\u0451\u0442. \u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0430 \u0440\u0430\u0443\u043D\u0434\u0430 \u0438\u0433\u0440\u043E\u043A \u0441 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u043C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u043C \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442, \u0435\u0441\u043B\u0438 \u0443 \u043D\u0435\u0433\u043E \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 5000 \u043E\u0447\u043A\u043E\u0432. \u041F\u0440\u0438 \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u0435 \u043B\u0443\u0447\u0448\u0438\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0438\u0433\u0440\u0430 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F \u0435\u0449\u0451 \u043E\u0434\u0438\u043D \u0440\u0430\u0443\u043D\u0434."),
            rule_section(:teams, "\u041A\u043E\u043C\u0430\u043D\u0434\u043D\u0430\u044F \u0438\u0433\u0440\u0430",
              "\u0414\u043E \u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0430\u0440\u0442\u0438\u0438 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0438\u0433\u0440\u0443 \u043A\u043E\u043C\u0430\u043D\u0434\u0430\u043C\u0438. \u0414\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0440\u0430\u0432\u043D\u044B\u0435 \u0441\u043E\u0441\u0442\u0430\u0432\u044B:",
              "- \u0427\u0435\u0442\u044B\u0440\u0435 \u0438\u0433\u0440\u043E\u043A\u0430: \u0434\u0432\u0435 \u043F\u0430\u0440\u044B.",
              "- \u0428\u0435\u0441\u0442\u044C \u0438\u0433\u0440\u043E\u043A\u043E\u0432: \u0434\u0432\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u043F\u043E \u0442\u0440\u0438 \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430 \u0438\u043B\u0438 \u0442\u0440\u0438 \u043F\u0430\u0440\u044B.",
              "- \u0412\u043E\u0441\u0435\u043C\u044C \u0438\u0433\u0440\u043E\u043A\u043E\u0432: \u0434\u0432\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u043F\u043E \u0447\u0435\u0442\u044B\u0440\u0435 \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430 \u0438\u043B\u0438 \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0430\u0440\u044B.",
              "\u0423 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u043E\u0434\u043D\u0430 \u043C\u0430\u0448\u0438\u043D\u0430 \u0438 \u043E\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442. \u041A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0434\u0435\u0440\u0436\u0438\u0442 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0438 \u0445\u043E\u0434\u0438\u0442 \u0432 \u0441\u0432\u043E\u044E \u043E\u0447\u0435\u0440\u0435\u0434\u044C, \u043D\u043E \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u0435, \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u044F \u0438 \u0437\u0430\u0449\u0438\u0442\u044B \u043E\u0431\u0449\u0438\u0435 \u0434\u043B\u044F \u0432\u0441\u0435\u0439 \u043A\u043E\u043C\u0430\u043D\u0434\u044B. \u041E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0432 \u0434\u0432\u0435 \u043A\u0430\u0440\u0442\u044B \u043D\u0430 200 \u043C\u0438\u043B\u044C \u0442\u043E\u0436\u0435 \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A\u043E \u0432\u0441\u0435\u0439 \u043C\u0430\u0448\u0438\u043D\u0435, \u0430 \u043D\u0435 \u043A \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E.",
              "\u0410\u0442\u0430\u043A\u0438 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043D\u0430 \u043C\u0430\u0448\u0438\u043D\u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u0447\u0430\u044E\u0449\u0435\u0439 \u043A\u043E\u043C\u0430\u043D\u0434\u044B. \u041E\u0442\u0432\u0435\u0442\u0438\u0442\u044C \u0437\u0430\u0449\u0438\u0442\u043E\u0439 \u043C\u043E\u0436\u0435\u0442 \u043B\u044E\u0431\u043E\u0439 \u0438\u0433\u0440\u043E\u043A \u0430\u0442\u0430\u043A\u043E\u0432\u0430\u043D\u043D\u043E\u0439 \u043A\u043E\u043C\u0430\u043D\u0434\u044B, \u0435\u0441\u043B\u0438 \u043D\u0443\u0436\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0435\u0441\u0442\u044C \u0443 \u043D\u0435\u0433\u043E \u0432 \u0440\u0443\u043A\u0435. \u0418\u043C\u0435\u043D\u043D\u043E \u043E\u043D \u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0445\u043E\u0434."),
            rule_section(:variants, "\u0414\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430",
              "\u041F\u0435\u0440\u0435\u0434 \u043D\u0430\u0447\u0430\u043B\u043E\u043C \u043F\u0430\u0440\u0442\u0438\u0438 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0447\u0438\u0441\u043B\u043E \u043E\u0447\u043A\u043E\u0432 \u0434\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u0438 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430:",
              "- \u041D\u0430\u043A\u043E\u043F\u043B\u0435\u043D\u0438\u0435 \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u0439 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0442\u044C \u0440\u0430\u0437\u043D\u044B\u0435 \u043D\u0435\u0438\u0441\u043F\u0440\u0430\u0432\u043D\u043E\u0441\u0442\u0438 \u0443\u0436\u0435 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0432\u0448\u0435\u0439\u0441\u044F \u043C\u0430\u0448\u0438\u043D\u0435. \u0414\u043B\u044F \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u044F \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u043F\u0440\u0438\u0434\u0451\u0442\u0441\u044F \u0443\u0441\u0442\u0440\u0430\u043D\u0438\u0442\u044C \u0438\u0445 \u0432\u0441\u0435. \u0414\u0432\u0430\u0436\u0434\u044B \u043D\u0430\u043B\u043E\u0436\u0438\u0442\u044C \u043E\u0434\u043D\u0443 \u0438 \u0442\u0443 \u0436\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0443\u044E \u043D\u0435\u0438\u0441\u043F\u0440\u0430\u0432\u043D\u043E\u0441\u0442\u044C \u043D\u0435\u043B\u044C\u0437\u044F. \u041A\u0440\u0430\u0441\u043D\u044B\u0439 \u0441\u0432\u0435\u0442 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0430 \u0434\u0432\u0438\u0436\u0443\u0449\u0443\u044E\u0441\u044F \u043C\u0430\u0448\u0438\u043D\u0443.",
              "- \u041F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0435 \u0441\u0431\u0440\u043E\u0441\u0430 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0432 \u043A\u043E\u043B\u043E\u0434\u0443, \u043A\u043E\u0433\u0434\u0430 \u0442\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F. \u041A\u0430\u0440\u0442\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0443\u0436\u0435 \u0441\u044B\u0433\u0440\u0430\u043B\u0438 \u0434\u043B\u044F \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F, \u0440\u0435\u043C\u043E\u043D\u0442\u0430 \u0438\u043B\u0438 \u0430\u0442\u0430\u043A\u0438, \u0432 \u043D\u043E\u0432\u0443\u044E \u043A\u043E\u043B\u043E\u0434\u0443 \u043D\u0435 \u0432\u0445\u043E\u0434\u044F\u0442.",
              "- \u0417\u0430\u0449\u0438\u0442\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0438\u0437 \u043A\u043E\u043B\u043E\u0434\u044B. \u0422\u043E\u0433\u0434\u0430 \u043D\u0435 \u0431\u0443\u0434\u0435\u0442 \u043D\u0438 \u0437\u0430\u0449\u0438\u0442\u044B \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0440\u0430\u0443\u043D\u0434\u0430, \u043D\u0438 \u043A\u043E\u043D\u0442\u0440\u0430\u0442\u0430\u043A. \u041E\u0431\u044B\u0447\u043D\u044B\u0435 \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u0440\u0435\u043C\u043E\u043D\u0442\u0430 \u0438 \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u0431\u0435\u0437 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0439."),
            rule_section(:counterflow, "\u0412\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435",
              "\u042D\u0442\u0430 \u043E\u043F\u0446\u0438\u044F \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0432 \u043A\u043E\u043B\u043E\u0434\u0443 \u00AB\u0412\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435\u00BB \u0438 \u00AB\u041A\u043E\u043D\u0435\u0446 \u0432\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0433\u043E \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F\u00BB. \u041E\u0431\u044B\u0447\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442\u0441\u044F \u0447\u0435\u0442\u044B\u0440\u0435 \u043A\u0430\u0440\u0442\u044B \u0430\u0442\u0430\u043A\u0438 \u0438 \u0448\u0435\u0441\u0442\u044C \u043A\u0430\u0440\u0442 \u0435\u0451 \u043E\u0442\u043C\u0435\u043D\u044B.",
              "\u041F\u043E\u0434 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043C \u0430\u0442\u0430\u043A\u0438 \u043C\u0430\u0448\u0438\u043D\u0430 \u0435\u0434\u0435\u0442 \u043D\u0430\u0437\u0430\u0434: \u043A\u0430\u0440\u0442\u044B \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u044F \u0432\u044B\u0447\u0438\u0442\u0430\u044E\u0442 \u043C\u0438\u043B\u0438 \u0438\u0437 \u0435\u0451 \u043F\u0440\u043E\u0431\u0435\u0433\u0430, \u043D\u043E \u043D\u0435 \u043D\u0438\u0436\u0435 \u043D\u0443\u043B\u044F. \u0427\u0442\u043E\u0431\u044B \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0442\u0430\u043A\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u043C\u0430\u0448\u0438\u043D\u0430 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u0434\u043E\u043B\u0436\u043D\u0430 \u0438\u043C\u0435\u0442\u044C \u043F\u0440\u0430\u0432\u043E \u0434\u0432\u0438\u0433\u0430\u0442\u044C\u0441\u044F; \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u0438 \u0442\u0430\u043A\u0436\u0435 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C. \u041A\u0430\u0440\u0442\u0430 \u043D\u0430 200 \u043C\u0438\u043B\u044C, \u043F\u043E\u0442\u0440\u0430\u0447\u0435\u043D\u043D\u0430\u044F \u043D\u0430 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u043D\u0430\u0437\u0430\u0434, \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0432 \u043E\u0431\u044B\u0447\u043D\u043E\u043C \u043B\u0438\u043C\u0438\u0442\u0435 \u0434\u0432\u0443\u0445 \u0442\u0430\u043A\u0438\u0445 \u043A\u0430\u0440\u0442 \u0437\u0430 \u0440\u0430\u0443\u043D\u0434.",
              "\u0412\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u0432\u044F\u0437\u0430\u0442\u044C \u0434\u0430\u0436\u0435 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0432\u0448\u0435\u0439\u0441\u044F \u043C\u0430\u0448\u0438\u043D\u0435 \u0438 \u043F\u0440\u0438 \u043D\u0430\u043B\u0438\u0447\u0438\u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u0439. \u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C \u0430\u0442\u0430\u043A\u0443, \u043F\u043E\u043A\u0430 \u043E\u043D\u0430 \u0443\u0436\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442, \u043D\u0435\u043B\u044C\u0437\u044F. \u0421\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u00AB\u041A\u043E\u043D\u0435\u0446 \u0432\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0433\u043E \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F\u00BB, \u0447\u0442\u043E\u0431\u044B \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u043D\u043E\u0440\u043C\u0430\u043B\u044C\u043D\u043E\u043C\u0443 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044E. \u042D\u0442\u0430 \u043A\u0430\u0440\u0442\u0430 \u043D\u0435 \u0443\u0441\u0442\u0440\u0430\u043D\u044F\u0435\u0442 \u0434\u0440\u0443\u0433\u0438\u0435 \u043D\u0435\u0438\u0441\u043F\u0440\u0430\u0432\u043D\u043E\u0441\u0442\u0438 \u0438 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u0438.",
              "\u00AB\u0410\u0441 \u0432\u043E\u0436\u0434\u0435\u043D\u0438\u044F\u00BB \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0438 \u043E\u0442 \u044D\u0442\u043E\u0439 \u0430\u0442\u0430\u043A\u0438. \u0415\u0441\u043B\u0438 \u0432\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0443\u0436\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442, \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0430\u0441\u0430 \u043E\u0442\u043C\u0435\u043D\u0438\u0442 \u0435\u0433\u043E. \u0410\u0441\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u0432\u0435\u0442\u0438\u0442\u044C \u0438 \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E: \u044D\u0442\u043E \u0431\u0443\u0434\u0435\u0442 \u043A\u043E\u043D\u0442\u0440\u0430\u0442\u0430\u043A\u0430 \u0441 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0439 \u043F\u0440\u0435\u043C\u0438\u0435\u0439."),
            rule_section(:instant_repair, "\u041C\u0433\u043D\u043E\u0432\u0435\u043D\u043D\u044B\u0439 \u0440\u0435\u043C\u043E\u043D\u0442",
              "\u041E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0439 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u043E\u0439 \u0432 \u043A\u043E\u043B\u043E\u0434\u0443 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u00AB\u041C\u0433\u043D\u043E\u0432\u0435\u043D\u043D\u044B\u0439 \u0440\u0435\u043C\u043E\u043D\u0442\u00BB \u2014 \u043E\u0431\u044B\u0447\u043D\u043E \u0434\u0432\u0435 \u043A\u0430\u0440\u0442\u044B. \u041E\u0434\u043D\u0430 \u0442\u0430\u043A\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0443\u0441\u0442\u0440\u0430\u043D\u044F\u0435\u0442 \u043E\u0434\u043D\u0443 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u0443\u044E \u043F\u0440\u043E\u0431\u043B\u0435\u043C\u0443. \u0412 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u043F\u043E\u0441\u043B\u0435 \u0432\u0437\u044F\u0442\u0438\u044F \u043A\u0430\u0440\u0442\u044B \u0441\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u0440\u0435\u043C\u043E\u043D\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043F\u0440\u043E\u0431\u043B\u0435\u043C\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter.",
              "\u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0442\u043E\u0433\u043E, \u0447\u0442\u043E \u0438\u043C\u0435\u043D\u043D\u043E \u0432\u044B \u0443\u0441\u0442\u0440\u0430\u043D\u0438\u043B\u0438:",
              "- \u041F\u043E\u0441\u043B\u0435 \u043E\u0442\u043C\u0435\u043D\u044B \u043A\u0440\u0430\u0441\u043D\u043E\u0433\u043E \u0441\u0432\u0435\u0442\u0430 \u043C\u043E\u0436\u043D\u043E \u0435\u0445\u0430\u0442\u044C, \u0435\u0441\u043B\u0438 \u043D\u0435 \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u0434\u0440\u0443\u0433\u0438\u0445 \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u0439, \u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u044E\u0449\u0438\u0445 \u043C\u0430\u0448\u0438\u043D\u0443. \u041C\u0433\u043D\u043E\u0432\u0435\u043D\u043D\u044B\u0439 \u0440\u0435\u043C\u043E\u043D\u0442 \u0442\u0430\u043A\u0436\u0435 \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442, \u043A\u043E\u0433\u0434\u0430 \u0432\u044B \u0435\u0449\u0451 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0442\u0435\u0441\u044C \u0442\u0440\u043E\u043D\u0443\u0442\u044C\u0441\u044F.",
              "- \u041F\u043E\u0441\u043B\u0435 \u0443\u0441\u0442\u0440\u0430\u043D\u0435\u043D\u0438\u044F \u043D\u0435\u0445\u0432\u0430\u0442\u043A\u0438 \u0442\u043E\u043F\u043B\u0438\u0432\u0430, \u043F\u0440\u043E\u043A\u043E\u043B\u0430 \u0438\u043B\u0438 \u0430\u0432\u0430\u0440\u0438\u0438 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u043D\u0443\u0436\u0435\u043D \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0441\u0432\u0435\u0442. \u0418\u0441\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u2014 \u043C\u0430\u0448\u0438\u043D\u0430 \u0441 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E\u043C \u043F\u0440\u043E\u0435\u0437\u0434\u0430.",
              "- \u041E\u0442\u043C\u0435\u043D\u0430 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u0438 \u0438\u043B\u0438 \u0432\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0433\u043E \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u0441\u043D\u0438\u043C\u0430\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0435 \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u0435. \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u044E\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C.",
              "\u041C\u0433\u043D\u043E\u0432\u0435\u043D\u043D\u044B\u0439 \u0440\u0435\u043C\u043E\u043D\u0442 \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u0437\u0430\u0449\u0438\u0442\u043E\u0439: \u043E\u043D \u043D\u0435 \u043F\u0440\u0435\u0434\u043E\u0442\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0431\u0443\u0434\u0443\u0449\u0438\u0435 \u0430\u0442\u0430\u043A\u0438, \u043D\u0435 \u0434\u0430\u0451\u0442 \u0435\u0449\u0451 \u043E\u0434\u043D\u043E\u0433\u043E \u0445\u043E\u0434\u0430 \u0438\u043B\u0438 \u043F\u0440\u0435\u043C\u0438\u0438 \u0438 \u043D\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u0438\u0442 \u0434\u043B\u044F \u043A\u043E\u043D\u0442\u0440\u0430\u0442\u0430\u043A\u0438."),
            rule_section(:custom_deck, "\u0421\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u0430\u044F \u043A\u043E\u043B\u043E\u0434\u0430",
              "\u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u0443\u044E \u043A\u043E\u043B\u043E\u0434\u0443 \u0438 \u0437\u0430\u0434\u0430\u0442\u044C \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043A\u0430\u0440\u0442 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0432\u0438\u0434\u0430. \u0417\u0430\u0449\u0438\u0442\u044B, \u0432\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0438 \u043C\u0433\u043D\u043E\u0432\u0435\u043D\u043D\u044B\u0439 \u0440\u0435\u043C\u043E\u043D\u0442 \u0432\u043A\u043B\u044E\u0447\u0430\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E: \u043E\u0434\u043D\u043E\u0433\u043E \u0443\u043A\u0430\u0437\u0430\u043D\u0438\u044F \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u0438\u0445 \u043A\u0430\u0440\u0442 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E.",
              "\u0421\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044F \u043A\u043E\u043B\u043E\u0434\u0443, \u043F\u0440\u0435\u0434\u0443\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u043F\u043E \u0448\u0435\u0441\u0442\u044C \u043A\u0430\u0440\u0442 \u043D\u0430 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u0443\u044E \u0440\u0430\u0437\u0434\u0430\u0447\u0443 \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443 \u0438 \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u043A\u0430\u0440\u0442 \u0434\u043B\u044F \u0441\u0430\u043C\u043E\u0439 \u0433\u043E\u043D\u043A\u0438. \u041A\u0440\u043E\u043C\u0435 \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u0439, \u043D\u0443\u0436\u043D\u044B \u043A\u0430\u0440\u0442\u044B, \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0449\u0438\u0435 \u0442\u0440\u043E\u043D\u0443\u0442\u044C\u0441\u044F \u0438 \u0438\u0437\u0431\u0430\u0432\u0438\u0442\u044C\u0441\u044F \u043E\u0442 \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u0439. \u041A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043A\u0430\u0440\u0442 \u0432\u0441\u0442\u0440\u0435\u0447\u043D\u043E\u0433\u043E \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u0438 \u0435\u0433\u043E \u043E\u0442\u043C\u0435\u043D\u044B \u043C\u043E\u0436\u043D\u043E \u043C\u0435\u043D\u044F\u0442\u044C \u0438 \u0431\u0435\u0437 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0432\u0441\u0435\u0439 \u043A\u043E\u043B\u043E\u0434\u044B."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0432 \u0440\u0443\u043A\u0435 \u0438\u043B\u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B.",
              "Enter: \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443; \u043F\u0440\u0438 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0441\u0442\u0438 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u0438\u043B\u0438 \u0443\u0441\u0442\u0440\u0430\u043D\u044F\u0435\u043C\u0443\u044E \u043F\u0440\u043E\u0431\u043B\u0435\u043C\u0443. \u0414\u043B\u044F \u043A\u0430\u0440\u0442\u044B, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043D\u0435\u043B\u044C\u0437\u044F \u0441\u044B\u0433\u0440\u0430\u0442\u044C, \u2014 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0441\u0431\u0440\u043E\u0441.",
              "Escape: \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0432\u044B\u0431\u043E\u0440 \u043A\u0430\u0440\u0442\u044B, \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u0438\u043B\u0438 \u0441\u0431\u0440\u043E\u0441\u0430.",
              "\u041F\u0440\u043E\u0431\u0435\u043B: \u0432\u0437\u044F\u0442\u044C \u043A\u0430\u0440\u0442\u0443.",
              "J: \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0431\u0435\u0437 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F.",
              "Delete: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0434\u043B\u044F \u0441\u0431\u0440\u043E\u0441\u0430.",
              "H: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0432 \u0440\u0443\u043A\u0435.",
              "I: \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u0432\u043E\u0439 \u043F\u0440\u043E\u0431\u0435\u0433, \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u044F \u0438 \u0437\u0430\u0449\u0438\u0442\u044B.",
              "Shift+I: \u0443\u0437\u043D\u0430\u0442\u044C \u043F\u0440\u043E\u0431\u0435\u0433, \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u044F \u0438 \u0437\u0430\u0449\u0438\u0442\u044B \u0432\u0441\u0435\u0445 \u043C\u0430\u0448\u0438\u043D.",
              "S: \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u0447\u0451\u0442.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u0434.",
              "Z: \u043D\u0430\u0439\u0442\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434. \u041D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0438 \u043A\u043E\u043D\u0442\u0440\u0430\u0442\u0430\u043A\u0438.",
              "Shift+Z: \u043D\u0430\u0439\u0442\u0438 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434. \u041D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0438 \u043A\u043E\u043D\u0442\u0440\u0430\u0442\u0430\u043A\u0438.",
              "Shift+C: \u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043F\u043E \u0432\u0438\u0434\u0443; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439.",
              "Shift+H: \u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043F\u043E \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u044E \u0438\u043B\u0438 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044E; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439.",
              "Shift+M: \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u043A\u0430\u0440\u0442.")
          ]
        end
      end
    end
